if(!G.sim&&P){ delete P.mercOut; if(G.mercId&&!P.merc) P.merc=G.mercId; }

delete P.raidSpliced;
// v16.xx, co-op hunt 2026-09-28: a hire is spent at the lift, so a raid that ended by the page going away leaves no hire
