if(P.mercOut&&typeof P.mercOut==='object'&&P.mercOut.dead){ P.credits-=MERC_DEATH; if(typeof P.mercOut.id==='string'){ var _moR=idRec(P.mercOut.id); _moR.standing=Math.min(_moR.standing,-1); } }
delete P.mercOut;

